"""Build dependency-free static detail pages and the shared dashboard ledger.
Canonical editable research lives in data/*.json. Run from any directory.
"""
import json, html, re
from pathlib import Path
P=Path(__file__).resolve().parents[1]
def read(n): return json.loads((P/'data'/f'{n}.json').read_text())
H=read('hotels')['hotels']; M=read('michelin'); A=read('activities')['activities']; C=read('costs'); F=read('flags')['flags']; B=read('brief')
D={**B,'hotels':H,'clusters':M['clusters'],'restaurants':M['restaurants'],'activities':A,'costs':C,'flags':F}
(P/'data.js').write_text('/* Generated by scripts/build_pages.py; edit data/*.json instead. */\nwindow.TRIP_DATA = '+json.dumps(D,ensure_ascii=False,indent=2)+';\n')
def e(s):return html.escape(str(s),quote=True)
def link(url,label='Official source'):return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>' if url else ''
def blank(s):return e(s) if s != '' and s is not None else '<span class="unknown" title="Not confirmed from the official source">—</span>'
def flags(x):return ' '.join(f'<a class="badge warn" href="flagged.html#{e(i)}">{e(i)}</a>' for i in x.get('flags',[]))
def socials(x):return '<br>'.join(link(u,k) for k,u in x.get('socials',{}).items())
NAV=[('index.html','Overview'),('executive-summary.html','Summary'),('hotels.html','Hotels'),('michelin.html','Michelin'),('activities.html','Activities'),('costs-booking.html','Dates & costs'),('questions.html','Questions'),('suggestions.html','Suggestions'),('flagged.html','Review flags'),('sources.html','Sources'),('entry-audit.html','Entry audit')]
def page(file,title,desc,body):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page" class="active"' if u==file else '')+f'>{t}</a>' for u,t in NAV)
 out=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0f172a"><meta name="description" content="{e(desc)}"><title>{e(title)} · China trip planning desk</title><link rel="stylesheet" href="assets/css/style.css?v=20261126-v1"><script src="assets/js/app.js?v=20261126-v1" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><div class="topbar-inner"><a class="brand" href="index.html">中 China trip <small>Evidence-first planning desk</small></a><nav class="mainnav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main" class="wrap"><section class="hero"><p class="eyebrow">TWO ADULTS · FEB 15–MAR 23, 2027</p><h1>{e(title)}</h1><p>{e(desc)}</p><div class="chips"><span class="chip">Reviewed Nov 26, 2026</span><span class="chip">81–84 days to preferred start</span><span class="chip">7-night hotel comparison</span><span class="chip">Official facts ≠ 2027 guarantees</span></div></section>
<div class="note">A dash means unverified, not zero. Prices are in CNY unless labelled USD. No hotel has a verified one-hour transit catchment or an official dated 2027 seven-night quote. <a href="flagged.html">See all review flags</a>.</div>{body}</main><footer>ChinaFun2 · 2 adults · Research snapshot (Nov 26, 2026), not a booking service. <a href="index.html">Back to dashboard</a> · <a href="research/entry-audit.md">Original entry audit</a></footer></body></html>'''
 (P/file).write_text(out)
def table(id,headers,rows,filter=True):
 tool=f'<div class="toolbar"><label for="{id}-search">Search these records</label><input id="{id}-search" data-filter="{id}" type="search" placeholder="City, venue, cuisine or review flag…"><span id="{id}-count" role="status">{len(rows)} of {len(rows)} rows shown</span></div>' if filter else ''
 head=''.join(f'<th scope="col" data-sort><button type="button">{e(h)} <span aria-hidden="true">↕</span></button></th>' for h in headers)
 return tool+f'<p class="table-hint">Scroll horizontally for all columns. Use column buttons to sort; blank values stay last.</p><div class="table-wrap" tabindex="0" role="region" aria-label="{e(id)} comparison"><table id="{id}" data-sortable><caption class="sr-only">{e(id)} records with source links and review flags</caption><thead><tr>{head}</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
cityrows=[[e(x['city']),e(x['edition']),e(x['count']),e(x['detail']),e(x['comparability']),link(x['source'])] for x in M['clusters']]
summary='''<div class="grid"><article class="card"><h2>Provisional choice: Shanghai</h2><p>Start with one city for seven nights: Mon Feb 15 → Mon Feb 22, 2027 (or split 14–28 nights across two cities if passport/visa rules permit). Shanghai offers 51 starred restaurants in the 2026 city subset and five venues with verified official published 2-adult set-menu totals (¥695 to ¥5,776).</p></article><article class="card"><h2>Critical 2026–2027 closures caught</h2><p><strong>Jinsha Site Museum (Chengdu)</strong> is closed Dec 5, 2025 – Apr 30, 2027; <strong>Ultraviolet (Shanghai)</strong> closed in 2025 and is removed from the 2026 MICHELIN Guide; <strong>Shanghai Museum People’s Square</strong> runs a paid special exhibition only through Nov 14, 2027 (use East Campus for free permanent galleries).</p></article><article class="card"><h2>Knowns &amp; open blockers</h2><p>Two adults, private ensuite room, Queen or larger bed, preferred start Feb 15–18, 2027 (81–84 days out). Live dated 2027 7-night hotel totals, written private-bath confirmation, passport/visa eligibility, and timestamped &lt;=60-minute transit matrices remain open before paying deposits.</p></article></div>'''
summary+=table('cities',['City','Edition / scope','Starred venues','Breakdown','Decision context','Official source'],cityrows)
summary+='''<h2 class="section">A closure-aware seven-night Shanghai draft — not a route-verified itinerary</h2><div class="card"><ol><li>Mon Feb 15: arrival, check-in, Xintiandi / Nanjing Road walk and Bund illumination (17:00–21:00 winter schedule). Monday-closed venues (Yu Garden, Power Station of Art, People’s Square Museum, Taian Table, Da Vittorio) are avoided.</li><li>Tue Feb 16: Yu Garden classical daytime garden (¥60 for two, 09:00–16:30) and Power Station of Art (¥0 general entry, 11:00–19:00). Note Shanghai Museum East is closed Tuesdays.</li><li>Wed Feb 17: Shanghai Museum East Campus in Pudong (10:00–18:00, walk-in passport entry ¥0) paired with Shanghai Tower 118F observatory (¥360 for two, visibility permitting).</li><li>Thu Feb 18: Wukang / Anfu Road walk + prebooked Michelin meal with published couple menu pricing (e.g., T’ang Court ¥888 dim sum lunch / ¥2,288 set, Yi Long Court ¥695 lunch / ¥2,304 dinner, or Taian Table ¥5,176–¥5,776 tasting).</li><li>Fri Feb 19: Shanghai Disneyland full day (from ¥950 for two on official resort tier calendar) or neighborhood Bib Gourmand crawl (Da Hu Chun, Mi Thai, Yuge · Zhanjiang).</li><li>Sat Feb 20 (Lantern Festival 2027): check crowd/event surcharges before visiting Old City / Yuyuan; consider Bund dining (Bao Li Xuan ¥3,576 degustation or Sir Elly’s ¥3,004 5-course set).</li><li>Sun Feb 21: flexible French Concession / Jing’an day or optional Zhujiajiao excursion (Kezhi Garden ¥40 for two; &gt;60m suburban trip).</li><li>Mon Feb 22: checkout/departure (or high-speed rail onward to Beijing/Chengdu/Guangzhou if extending to 14–28 nights with an eligible visa).</li></ol><p>All hotel-to-site and hotel-to-restaurant transit durations remain unverified until a finalist hotel is chosen. See <a href="activities.html">official activity schedules</a>, <a href="michelin.html">restaurant sources</a>, and <a href="flagged.html">review flags</a>.</p></div>'''
summary+='<div class="note blue">Official Spring Festival break: Feb 5–13, 2027; Feb 14 is a makeup workday; Lantern Festival falls on Sat Feb 20, 2027. Starting Feb 15 avoids the statutory holiday week, though local event schedules and rates still require direct confirmation. '+link(C['stay_options'][0]['source'],'State Council holiday notice')+'</div>'
page('executive-summary.html','The decision brief','Four candidate cities, closure-checked 2026–2027 ground truth, and the remaining blockers before booking.',summary)
rows=[]
for x in H:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong><p>'+e(x['area'])+'</p>',blank(x['rank']),blank(x['bed']),blank(x['bath']),e(x['evidence'])+'<p>'+e(x['amenities'])+'</p><p class="muted">'+e(x['fitNote'])+'</p>',blank(x['total']),blank(x['transit']),blank(x['activityTransit']),link(x['roomSource'],'Official room/property page')+'<br>'+link(x['bookSource'],'Official booking')+'<p>'+flags(x)+'</p>'])
page('hotels.html','Hotel candidates — room evidence verified, totals & transit open','Private ensuite + Queen/King for two is required. Rebrands (Upper House Shanghai/Chengdu), corrected Marriott/Hilton property codes, and Ritz-Carlton Pudong renovation notices are reflected below.',table('hotels',['City / candidate','Verified rank','Bed confirmed','Private bath confirmed','Official room evidence / amenities / caveats','Official 7-night 2027 total','Michelin ≤60m count','Activities ≤60m routes','Sources / flags'],rows)+'<div class="note">Only room facts verified on official brand pages are shown. Blank bed/bath/quote/transit cells require category-level or dated-engine confirmation — never proxy multiplication. <a href="costs-booking.html">Compare 7-night date windows and upcoming 60d/30d/14d checkpoints</a>.</div><p><a href="data/hotels.json">Download hotel JSON</a></p>')
rows=[]
for x in M['restaurants']:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong>',e(x['status'])+'<br><small>'+e(x['distinction'])+'</small>',e(x['cuisine']),blank(x['guideBand']),blank(x['coupleTotal']),blank(x['hours'])+'<p>'+e(x['exceptions'])+'</p>',link(x['guide'],'MICHELIN Guide')+(('<br>'+link(x['venue'],'Official venue / menu')) if x.get('venue') else '')+'<p>'+flags(x)+'</p>',socials(x)])
page('michelin.html','Michelin restaurants — Starred vs Bib Gourmand & Selected','Starred venues are separated from Bib Gourmand and Guide Selected listings. Five Shanghai venues include official published 2-adult menu arithmetic; unconfirmed meal totals stay blank.',table('restaurants',['City / restaurant','Distinction / edition','Cuisine','Guide band','Official published menu basis · two adults','Hours / closures / exceptions','Official sources / flags','Reviews & discovery (YT / IG / TT)'],rows)+'<div class="note">Verified 2-adult official menu totals: <strong>Yi Long Court</strong> (1★, ¥695 lunch / ¥2,304 dinner incl. 16.6%), <strong>T’ang Court</strong> (2★, ¥888 lunch / ¥2,288 set incl. charges), <strong>Sir Elly’s</strong> (Selected non-starred, ¥3,004 5-course set incl. 16.6%), <strong>Bao Li Xuan</strong> (2★, ¥3,576 degustation incl. 10% + 6% VAT), and <strong>Taian Table</strong> (3★, ¥5,176 / ¥5,776 before supplements). <a href="flagged.html#R04">Ultraviolet and Lan Ting are closed/delisted in 2026</a>; <a href="flagged.html#R05">lameloise.com.cn is quarantined</a>.</div><p><a href="data/michelin.json">Download restaurant and city JSON</a></p>')
rows=[]
for x in A:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong>',blank(x['schedule']),blank(x['cost']),blank(x['transit']),e(x['exception']),link(x['source'],'Official source')+(('<br>'+link(x['officialLink'],'Visitor / booking page')) if x.get('officialLink') and x.get('officialLink')!=x.get('source') else '')+'<p>'+flags(x)+'</p>',socials(x)])
page('activities.html','Culture & sightseeing — schedules, 2-adult tickets & closure alerts','Official hours, 2-adult ticket pricing, Monday/Tuesday closure rules, and confirmed 2026–2027 facility closures across all four candidate cities.',table('activities',['City / activity','Published regular hours','Two-adult cost / product','Door-to-door public transit','Exceptions / closure & booking caveats','Official source / flags','Reviews & discovery (YT / IG / TT)'],rows)+'<div class="note"><strong>Closure alert (<a href="flagged.html#A04">A04</a>):</strong> Jinsha Site Museum in Chengdu is officially closed Dec 5, 2025 – Apr 30, 2027; Shanghai Museum People’s Square runs a paid special exhibition only through Nov 14, 2027 (use Shanghai Museum East for free permanent galleries).</div><p><a href="data/activities.json">Download activity JSON</a></p>')
body='<div class="grid"><article class="card"><h2>Today (Nov 26, 2026): 81–84 days out</h2><p>November 26, 2026 is 81 days before Feb 15 and 84 days before Feb 18, 2027. The 90-day mark (Nov 17–20) has passed; capture a refundable direct ceiling quote now and recheck at the 60-day checkpoint (Dec 17–20, in 21–24 days).</p></article><article class="card"><h2>1–2 weeks vs 2–4 weeks</h2><p>Standard hotel comparisons use 7-night blocks (Feb 15–22 or Mar 1–8). If extending to 14–28 nights inside Feb 15–Mar 23, note China’s 240-hour (10-day) transit-without-visa cannot cover stays beyond 10 days (<a href="flagged.html#E01">E01</a>).</p></article></div>'
body+=table('stays',['Check-in','Check-out','Nights','Official hotel total · two adults','Date context / flags'],[[e(x['checkin']),e(x['checkout']),e(x['nights']),blank(x['official_total']),link(x['source'],'Official holiday context')+'<br>'+flags(x)] for x in C['stay_options']])
body+='<h2>Target booking / repricing checkpoints</h2><p>Exact calendar dates for Feb 15–18, 2027 check-ins. Links open official hotel portals to capture live refundable quotes, not pre-claimed savings.</p>'
body+=table('checkpoints',['Lead days','For Feb 15 start','For Feb 18 start','Action as of Nov 26, 2026','Quote source / flags'],[[e(x['lead_days']),e(x['target_start']),e(x['target_end']),e(x['action']),link(x['source'],'Official quote engine')+'<br>'+flags(x)] for x in C['booking_windows']])
body+='<details><summary>Quarantined aggregator observations — not bookable quotes</summary><p>Prior traveldeals.com research observations lack exact stay, room, tax and cancellation metadata. They cannot establish 2027 totals, savings or an optimum booking window. To avoid implying comparable rates, the numbers are excluded from these decision tables and retained only in the labelled audit records in the JSON download. Official quote columns above remain empty. See <a href="flagged.html#B01">B01</a> and <a href="flagged.html#B02">B02</a>.</p></details><p><a href="data/costs.json">Download dates / costs and quarantined observations (JSON)</a></p>'
page('costs-booking.html','Dates, costs & booking','Calendar-checked 7-night comparison blocks and upcoming 60d / 30d / 14d repricing checkpoints.',body)
page('questions.html','Questions & missing information','Resolve these before paying non-refundable deposits. Never post passport numbers or sensitive documents.', ''.join('<article class="card question"><h2>'+e(x['q'])+'</h2><span class="badge warn">'+e(x['state'])+'</span><p><strong>Known:</strong> '+e(x['answer'])+'</p><p><strong>Next:</strong> '+e(x['next'])+'</p></article>' for x in B['questions'])+'<div class="note">Entry cannot be inferred from where you live. <a href="entry-audit.html">Read the official-source entry audit</a>.</div>')
page('suggestions.html','Suggestions — review before implementing','Actionable research and itinerary proposals presented for review before changing trip scope or placing bookings.', ''.join('<article class="card question"><h2>'+e(x['title'])+'</h2><p>'+e(x['desc'])+'</p><p>Value: '+e(x['impact'])+' · Effort: '+e(x['effort'])+' · Priority: '+e(x['rec'])+'</p></article>' for x in B['suggestions'])+'<article class="card question"><h2>Capture a finalist route matrix and refundable rate log</h2><p>Choose 2–3 finalist hotels in one base city (for example The Langham Xintiandi, The Peninsula Shanghai, and Jing An Shangri-La). Record refundable 7-night King/ensuite quotes and weekday/weekend subway/bus routes to active 2026 Michelin venues and open sights before assigning a final rank.</p></article>')
page('flagged.html','Flagged for review','Every closure, delisting, schedule discrepancy, unverified price, and route blocker stays visible with official source links.', ''.join(f'<article class="card question" id="{e(x["id"])}"><span class="badge warn">{e(x["status"])}</span><h2>{e(x["id"])} · {e(x["scope"])}</h2><p>{e(x["issue"])}</p><p><strong>Next:</strong> {e(x["next"])}</p>{link(x["source"])}</article>' for x in F))
unique={}
for group in [H,M['restaurants'],A]:
 for x in group: unique[x.get('official_url')]=x['name']
for x in M['clusters']:unique[x['source']]=x['city']+' selection release'
for x in F: unique.setdefault(x['source'],x['scope'])
page('sources.html','Sources & verification method','Official source links sit alongside each record; a linked homepage does not verify every blank metric.', '<div class="card"><h2>Evidence levels (reviewed Nov 26, 2026)</h2><ol><li>Official property, venue, museum, government or MICHELIN pages support only the explicitly stated facts.</li><li>Official published 2-adult menu totals (5 Shanghai venues) reflect current 2026 PDFs/booking FAQs, not guaranteed 2027 tariffs.</li><li>Aggregator observations and compromised third-party domains (lameloise.com.cn) are quarantined.</li><li>Verified YouTube, TikTok, and Instagram links provide visual context only; never use creator posts over official schedules.</li><li>City MICHELIN counts are not route-verified &lt;=60-minute hotel catchments. Blank means unverified, never zero.</li></ol><p><a href="RESEARCH_REVIEW.md">Full reconciliation audit</a> · <a href="research/entry-audit.md">Original entry audit</a> · <a href="COORDINATION.md">Coordination history</a></p></div>'+table('sources',['Record / scope','Official source'],[[e(n),link(u)] for u,n in unique.items() if u]))
def inline(s):
 s=e(s);s=re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',r'<a href="\2" target="_blank" rel="noopener noreferrer">\1</a>',s);return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
parts=[]; labels=None
for line in (P/'research/entry-audit.md').read_text().splitlines():
 if line.startswith('#'):
  n=min(len(line)-len(line.lstrip('#')),4);parts.append(f'<h{n}>'+inline(line.lstrip('# '))+f'</h{n}>');labels=None
 elif line.startswith('|'):
  cells=[v.strip() for v in line.strip('|').split('|')]
  if all(re.fullmatch(r'[:\- ]+',v) for v in cells):continue
  if labels is None:labels=cells;continue
  parts.append('<section class="audit-row"><h3>'+inline(cells[0])+'</h3><dl>'+''.join('<dt>'+inline(label)+'</dt><dd>'+inline(value)+'</dd>' for label,value in zip(labels[1:],cells[1:]))+'</dl></section>')
 elif line.strip():parts.append('<p>'+inline(line)+'</p>');labels=None
page('entry-audit.html','Entry, health & eligibility audit','Independent audit retained from session b679d5a6; personal eligibility remains unresolved.', '<div class="card audit">'+''.join(parts)+'</div>')
print(f'Built 10 detail pages; {len(H)} hotels, {len(M["restaurants"])} restaurants, {len(A)} activities, {len(F)} flag groups.')
